export type ParsedSlashTrancheInstruction<
  TProgram extends string = typeof LVRT_INSURANCE_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    engineSigner: TAccountMetas[0];
    config: TAccountMetas[1];
    fund: TAccountMetas[2];
    lvrtMint: TAccountMetas[3];
    stakeVault: TAccountMetas[4];
    slashEscrow: TAccountMetas[5];
    lvrtTokenProgram: TAccountMetas[6];
  };
  data: SlashTrancheInstructionData;
};

export function parseSlashTrancheInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedSlashTrancheInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 7) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 7,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      engineSigner: getNextAccount(),
      config: getNextAccount(),
      fund: getNextAccount(),
      lvrtMint: getNextAccount(),
      stakeVault: getNextAccount(),
      slashEscrow: getNextAccount(),
      lvrtTokenProgram: getNextAccount(),
    },
    data: getSlashTrancheInstructionDataDecoder().decode(instruction.data),
  };
}
